#include <iostream>
#include <vector>

template<class C>
auto total(const C& values)
{
    typename C::value_type result{};
    for (const auto& value : values) result += value;
    return result;
}

int main()
{
    const std::vector<int> pages{3, 5, 8};
    std::cout << total(pages) << '\n';
}
